// SCOPE GATE — fail-closed. Only the three v1 full-access role groups may use
// the assistant (ADR-005). Any unknown / missing / unmapped role → denied.
// This is defence-in-depth: the UI already hides the bubble for other roles.
const body = $input.first().json.body || {};
const question = (body.question || '').toString().trim();

// Normalise DB role strings to canonical groups (mirror of App.jsx ROLE_GROUP).
const ROLE_GROUP = {
  procurement_manager: 'procurement', head_of_procurement: 'procurement', category_manager: 'procurement',
  it: 'it', it_manager: 'it',
  user: 'user', ops_manager: 'user', requester: 'user', budget_owner: 'user',
  controlling: 'controlling',
  admin: 'admin',
  legal: 'legal'
};
const V1_ALLOWED = ['procurement', 'admin', 'controlling'];

const rawRole = (body.role || '').toString();
const group = ROLE_GROUP[rawRole] || null;
const allowed = group !== null && V1_ALLOWED.includes(group);

if (!question) {
  return [{ json: { denied: true, reason: 'empty_question', answer: 'Please ask a question about your orders, budget, suppliers, or spend.' } }];
}
if (!allowed) {
  return [{ json: { denied: true, reason: 'role_not_in_v1', role: rawRole, group,
    answer: 'The Ask assistant is being rolled out to procurement, controlling, and admin first. It will be available to your role soon.' } }];
}

// Scope context carried forward. In v1 branch scope is NOT enforced server-side
// (single shared JWT, RLS USING(true)) — these full-access roles see all branches.
// Recorded here so the SSO migration can flip it to a real JWT-claim filter.
return [{ json: {
  denied: false,
  question,
  role: rawRole,
  group,
  email: (body.email || '').toString(),
  branchIds: Array.isArray(body.branchIds) ? body.branchIds : [],
  costCenterId: (body.costCenterId || '').toString()
} }];

// PRE-FETCH BUNDLE — read-only, scoped PostgREST GETs. No tool-call loop (one
// workflow run = one set of fetches), to keep n8n execution volume low.
// Fetches the caller's data per the ADR-005 read surfaces PLUS summary rollups
// (spend-by-category, budget-by-cost-centre). The assistant answers ONLY from
// what this bundle returns (I-9).
const ctx = $input.first().json;
const POSTGREST = $env.POSTGREST_URL || 'https://postgrest-production-7960.up.railway.app';
const JWT = $env.POSTGREST_JWT;
const H = { 'Authorization': 'Bearer ' + JWT, 'Accept': 'application/json' };
const q = (n) => (ctx.question || '').toLowerCase().includes(n);

const get = async (path) => {
  try {
    const r = await this.helpers.httpRequest({ method: 'GET', url: POSTGREST + path, headers: H, json: true });
    return Array.isArray(r) ? r : (r ? [r] : []);
  } catch (e) { return []; }
};

// current fiscal period e.g. 2026-Q2
const now = new Date();
const period = now.getFullYear() + '-Q' + Math.ceil((now.getMonth() + 1) / 3);

// 1) OPEN TICKETS / ORDER STATUS — board view (limited). If the question names a
//    ticket reference (TS-YYYY-XXXX) fetch that one too.
const refMatch = (ctx.question.toUpperCase().match(/TS-\d{4}-\d{3,5}/) || [])[0];
const sources = [];

const openTickets = await get('/open_tickets_board?limit=40');
if (openTickets.length) sources.push('open_tickets_board');

let namedTicket = [];
if (refMatch) {
  namedTicket = await get('/tickets?reference=eq.' + encodeURIComponent(refMatch) + '&limit=1');
  if (namedTicket.length) sources.push('tickets:' + refMatch);
}

// 2) BUDGET — command center for the current period (branch×category health).
const budget = await get('/budget_command_center?period=eq.' + encodeURIComponent(period) + '&limit=80');
if (budget.length) sources.push('budget_command_center');

// 3) SUPPLIER — if the question seems supplier-oriented, pull compliance summary.
//    Try to extract a supplier name token (capitalised word) for a targeted look.
let suppliers = [];
let supplierCompliance = [];
if (q('supplier') || q('vendor') || q('compliant') || q('contract') || q('expir')) {
  supplierCompliance = await get('/supplier_compliance_summary?limit=60');
  if (supplierCompliance.length) sources.push('supplier_compliance_summary');
  // contracts expiring soon (the renewal/expiry story)
  const expiring = await get('/contracts_expiring?limit=40');
  if (expiring.length) { suppliers = expiring; sources.push('contracts_expiring'); }
}

// 4) SPEND ANALYTICS + ROLLUPS — invoices are the spend truth; budget_positions
//    carry the reconciled spent. Provide both a category rollup and a
//    cost-centre rollup, computed from budget_positions for the period.
const budgetPositions = await get('/budget_positions?period=eq.' + encodeURIComponent(period) + '&limit=200');
if (budgetPositions.length) sources.push('budget_positions');

const spendByCategory = {};
const budgetByCostCentre = {};
for (const b of budgetPositions) {
  const cat = b.category || 'unknown';
  spendByCategory[cat] = (spendByCategory[cat] || 0) + Number(b.spent || 0);
  const cc = b.cost_center_id || 'unassigned';
  if (!budgetByCostCentre[cc]) budgetByCostCentre[cc] = { budget: 0, committed: 0, spent: 0 };
  budgetByCostCentre[cc].budget += Number(b.budget || 0);
  budgetByCostCentre[cc].committed += Number(b.committed || 0);
  budgetByCostCentre[cc].spent += Number(b.spent || 0);
}

const bundle = {
  meta: { period, role: ctx.group, askedBy: ctx.email, branchScopeEnforced: false },
  question: ctx.question,
  openTickets,
  namedTicket,
  budgetHealth: budget,
  supplierCompliance,
  contractsExpiringSoon: suppliers,
  rollups: { spendByCategory, budgetByCostCentre }
};

return [{ json: { ctx, bundle, sources } }];

// CLAUDE — answers ONLY from the pre-fetched TrueSpend bundle (I-9). No external
// knowledge, no web tool. If the answer is not in the data, it says so.
const { ctx, bundle, sources } = $input.first().json;
const ANTHROPIC_KEY = $env.ANTHROPIC_API_KEY;

const system = `You are TrueSpend's internal procurement assistant. You answer questions about orders, budget, suppliers, and spend.

HARD RULES (must follow):
1. Answer ONLY using the TrueSpend DATA provided below. NEVER use outside or general knowledge.
2. If the answer is not present in the provided data, reply exactly: "I don't have that in TrueSpend." Do not guess.
3. You are read-only. Never claim to have changed, approved, ordered, or paid anything.
4. Be concise. Prefer concrete figures (EUR amounts, dates, references) straight from the data.
5. All amounts are EUR unless stated. The current period is ${bundle.meta.period}.`;

const prompt = `QUESTION:\n${ctx.question}\n\nTRUESPEND DATA (this is the ONLY source you may use):\n${JSON.stringify(bundle, null, 1)}\n\nAnswer the question using only the data above. If it is not answerable from this data, say "I don't have that in TrueSpend."`;

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.anthropic.com/v1/messages',
  headers: {
    'x-api-key': ANTHROPIC_KEY,
    'anthropic-version': '2023-06-01',
    'content-type': 'application/json'
  },
  body: JSON.stringify({
    model: 'claude-sonnet-4-6',
    max_tokens: 1024,
    system,
    messages: [{ role: 'user', content: prompt }]
  }),
  json: true
});

const answer = (response.content && response.content[0] && response.content[0].text)
  ? response.content[0].text.trim()
  : "I don't have that in TrueSpend.";

return [{ json: { answer, sources, denied: false } }];
